int w, n;

int t = 0;

int dp[1001][1001];

vector<P> vec;



int rec(int i, int j){

	if(dp[i][j] >= 0) return dp[i][j];

	int res;

	if(i == n) res = 0;

	else if(j < vec[i].sec) res = rec(i+1, j);

	else res = max(rec(i+1, j), rec(i+1, j-vec[i].sec)+vec[i].fi);

	return dp[i][j] = res;

}



