#include "stdc++.h"



using namespace std;



#define MAX 1000

#define INF (1e9)



struct Edge{

    int to,cost,c;

    Edge(int to,int cost,int c) :

        to(to),cost(cost),c(c) {}

};



int main(){

    int M,D,N,K;

    int d[MAX][1<<6];    

    while(cin >> M >> N >> K >> D, M){

        vector<Edge> G[MAX];

        vector<int> cake(M);

        for(int i = 0 ; i < M ; i++){

            cin >> cake[i];

        }

        int idx = 0,c;

        string a,b;

        map<string,int> mp;

        for(int i = 0 ; i < D ; i++){

            cin >> a >> b >> c;

            if(!mp.count(a)) mp[a] = idx++;

            if(!mp.count(b)) mp[b] = idx++;

            if(a[0] == 'C'){

                G[mp[b]].push_back(Edge(mp[a],c,a[1]-'1'));             

            }else{

                G[mp[b]].push_back(Edge(mp[a],c,-1));           

            }

            if(b[0] == 'C'){

                G[mp[a]].push_back(Edge(mp[b],c,b[1]-'1'));

            }else{

                G[mp[a]].push_back(Edge(mp[b],c,-1));           

            }



        }

        int s = mp["H"],t = mp["D"];

        for(int i = 0 ; i < MAX ; i++){

            for(int j = 0 ; j < (1<<6) ; j++){

                d[i][j] = INF;

            }

        }

        d[s][0] = 0;

        bool update = 1;

        while(update){

            update = 0;

            for(int i = 0 ; i < (int)mp.size() ; i++){

                for(int j = 0 ; j < (int)G[i].size() ; j++){

                    Edge e = G[i][j];

                    for(int S = (1<<6)-1 ; S >= 0 ; S--){

                        int ncost = d[i][S];

                        if(ncost == INF) continue;

                        ncost += e.cost*K;

                        if(e.c == -1){

                            if(ncost < d[e.to][S]){

                                d[e.to][S] = ncost;

                                update = 1;

                            }

                        }else{

                            if(S >> e.c & 1) continue;

                            if(ncost-cake[e.c] < d[e.to][S|(1<<e.c)]){

                                d[e.to][S|(1<<e.c)] = ncost-cake[e.c];

                                update = 1;

                            }

                        }

                    }

                }

            }

        }

        int res = INF;

        for(int i = 0 ; i < (1<<6) ; i++){

            res = min(res, d[t][i]);

        }

        cout << res << endl;

    }

    return 0;

}

#include<iostream>

using namespace std;



bool visit[26],g[26][26];



bool dfs(int v){

  visit[v] = true;

  bool f = false;

  for(int i=0;i<26;i++)

    if(g[v][i]){

      f = true;

      if(!visit[i])dfs(i);

    }

  return f;

}



int graph_num(void){

  int res = 0;

  for(int i=0;i<26;i++)

    if(!visit[i] && dfs(i))res++;

  return res;

}



int main(){

  int i,n,pre[26],suf[26],h,t;

  string s;



  while(cin>>n && n){

    for(i=0;i<26;i++){

      visit[i] = false;

      pre[i] = suf[i] = 0;

      for(int j=0;j<26;j++)g[i][j] = false;

    }



    for(i=0;i<n;i++){

      cin >> s;

      h = s[0]-'a', t = s[(int)s.size()-1]-'a';



      pre[h]++;

      suf[t]++;

      g[h][t] = g[t][h] = true;

    }



    if(graph_num() != 1)printf("NG
");

    else{

      for(i=0;i<26;i++)if(pre[i] != suf[i])break;



      if(i==26)printf("OK
");

      else printf("NG
");

    }

  }

}

