/** Problem0244 : Hot Spring Trip **/

int cost[300][300];



int main()

{

	int N, M;



	while (cin>>N>>M, N||M) {

		rep(i, 300) rep(j, 300)

			cost[i][j] = i==j?0:INF;



		rep(i, M) {

			int a, b, c; cin>>a>>b>>c;

			a--, b--;

			cost[a][b] = cost[b][a] = c;

		}



		vector<P> can_free;

		rep(i, N) {

			rep(j, N) {

				if (cost[i][j]!=INF && i!=j) {

					rep(k, N) {

						if (cost[j][k]!=INF && i!=k && j!=k)

							can_free.push_back(P(i, k));

					}

				}

			}

		}



		rep(k, N) {

			rep(i, N) {

				rep(j, N) {

					cost[i][j] = min(cost[i][j], cost[i][k]+cost[k][j]);

				}

			}

		}



		int ans=cost[0][N-1];

		rep(i, can_free.size()) {

			ans = min(cost[0][can_free[i].x]+cost[can_free[i].y][N-1], ans);

		}



		cout << ans << endl;

	}

}

