template<class T>

size_t uniq(vector<T> &v){

    sort(v.begin(), v.end());

    v.erase(unique(v.begin(), v.end()), v.end());

    return v.size();

}

template<class T>

size_t uniq(T *l, size_t n){

    sort(l,l+n);

    return unique(l,n) - l;

}

