int dp[101010][10];



int dfs(int i = 1, int bit = 0) {

  if (i == h) {

    return 0;

  }

  bit |= b[i];



  int &ret = dp[i][bit];

  if (~ret)

    return ret;



  ret = 0;

  if (bit == 0)

    ret = max(ret, dfs(i + 1, 0b111) + 2);

  if ((bit & (0b100)) == 0)

    ret = max(ret, dfs(i + 1, 0b110) + 1);

  if ((bit & (0b010)) == 0)

    ret = max(ret, dfs(i + 1, 0b111) + 1);

  if ((bit & (0b001)) == 0)

    ret = max(ret, dfs(i + 1, 0b011) + 1);

  ret = max(ret, dfs(i + 1, 0));



  return ret;

}



