    queue<P> que;



    rep(i,n)for(int k=x1[i];k<x2[i];k++){

    for(int j=y1[i];j<y2[i];j++)used[j][k] = true;

      }



    rep(i,limy){

      rep(j,limx){

    if(!used[i][j]){

      que.push(P(j,i));

      cnt++;

      used[i][j] = true;

      while(!que.empty()){

        P p = que.front(); que.pop();

        rep(k,4){

          int nx = p.F+dx[k],ny = p.S+dy[k];

          if(0<=nx && nx <limx-1 && 0<= ny && ny <limy-1 && !used[ny][nx]){

        used[ny][nx] = true;

        que.push(P(nx,ny));

          }

        }



      }

    }

      }

    }







    cout << cnt << endl;











  }

  return 0;

}

